#include <bits/stdc++.h>
using namespace std;

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        long long a[n];
        for (int i = 0; i < n; i++) cin >> a[i];
        long long sum = 0;
        bool ok = true;
        for (int i = 0; i < n - 1; i++) {
            sum += a[i];
            if (sum <= 0) ok = false;
        }
        sum = 0;
        for (int i = n - 1; i > 0; i--) {
            sum += a[i];
            if (sum <= 0) ok = false;
        }
        if (ok) cout << "YES" << endl;
        else cout << "NO" << endl;
    }
    return 0;
}
